import * as React from "react"
import { useEffect, useMemo, useState } from "react"
import { addPropertyControls, ControlType } from "framer"

type Language = "en" | "vi"
type Office = {
    id: string
    flag: string
    city: string
    cityVi: string
    country: string
    countryVi: string
    company: string
    address: string
    addressVi: string
    hours: string
    hoursVi: string
    directions: string
    mapQuery: string
}

const offices: Office[] = [
    {
        id: "dubai", flag: "🇦🇪", city: "Dubai", cityVi: "Dubai",
        country: "United Arab Emirates", countryVi: "Các Tiểu vương quốc Ả Rập Thống nhất",
        company: "Botanika Cortex Trading LLC",
        address: "Office 105 (OFF105), Garhoud Building, Al Garhoud, Dubai, United Arab Emirates",
        addressVi: "Văn phòng 105 (OFF105), Garhoud Building, Al Garhoud, Dubai, Các Tiểu vương quốc Ả Rập Thống nhất",
        hours: "Mon – Sun · 8:30 AM – 6:30 PM (UTC+4) · Cut-off 14:00",
        hoursVi: "Thứ Hai – Chủ Nhật · 8:30 – 18:30 (UTC+4) · Giờ chốt: 14:00",
        directions: "https://maps.app.goo.gl/bqQPeXiBTPxSDTzJ7",
        mapQuery: "Garhoud Star building, Al Garhoud, Dubai, United Arab Emirates",
    },
    {
        id: "vietnam", flag: "🇻🇳", city: "Ho Chi Minh City", cityVi: "Thành phố Hồ Chí Minh",
        country: "Vietnam", countryVi: "Việt Nam",
        company: "Botanika Vietnam Company Limited",
        address: "59 Đ. Số 61 - TML, Cát Lái, Hồ Chí Minh, Việt Nam",
        addressVi: "59 Đ. Số 61 - TML, Cát Lái, Hồ Chí Minh, Việt Nam",
        hours: "Mon – Sun · 8:30 AM – 6:30 PM (UTC+7) · Cut-off 14:00",
        hoursVi: "Thứ Hai – Chủ Nhật · 8:30 – 18:30 (UTC+7) · Giờ chốt: 14:00",
        directions: "https://maps.app.goo.gl/mnvdhTkNQmYoALyp9",
        mapQuery: "59 Đường Số 61 TML, Cát Lái, Hồ Chí Minh, Việt Nam",
    },
    {
        id: "panama", flag: "🇵🇦", city: "Panama City", cityVi: "Thành phố Panama",
        country: "Republic of Panama", countryVi: "Cộng hòa Panama",
        company: "Bonsai Foundation",
        address: "55th Street East, SL55 Building, 21st Floor, Office 2, Panama City, Republic of Panama",
        addressVi: "55th Street East, tòa nhà SL55, tầng 21, văn phòng 2, Thành phố Panama, Cộng hòa Panama",
        hours: "Mon – Sun · 8:30 AM – 6:30 PM (UTC-5) · Cut-off 14:00",
        hoursVi: "Thứ Hai – Chủ Nhật · 8:30 – 18:30 (UTC-5) · Giờ chốt: 14:00",
        directions: "https://maps.app.goo.gl/ZByWK8SR3ZJZEyBt7",
        mapQuery: "SL55 Building, 55th Street East, Panama City, Panama",
    },
    {
        id: "georgia", flag: "🇬🇪", city: "Tbilisi", cityVi: "Tbilisi",
        country: "Georgia", countryVi: "Gruzia",
        company: "Bonsai Holdings LLC",
        address: "22 Bakhtrioni Street, Tbilisi, Georgia",
        addressVi: "Số 22 đường Bakhtrioni, Tbilisi, Gruzia",
        hours: "Mon – Sun · 8:30 AM – 6:30 PM (UTC+4) · Cut-off 14:00",
        hoursVi: "Thứ Hai – Chủ Nhật · 8:30 – 18:30 (UTC+4) · Giờ chốt: 14:00",
        directions: "https://maps.app.goo.gl/TGUVZq7HLAMM9SMz5",
        mapQuery: "22 Bakhtrioni Street, Tbilisi, Georgia",
    },
]

function readLanguage(): Language {
    if (typeof window === "undefined") return "en"
    const selected = (window as Window & { __botanikaInlineLanguage?: Language }).__botanikaInlineLanguage
    if (selected) return selected
    try {
        const stored = window.localStorage.getItem("botanika-language")
        if (stored === "vi") return "vi"
        if (stored === "en") return "en"
    } catch {}
    return /^\/vi(?:\/|$)/.test(window.location.pathname) ? "vi" : "en"
}

function readHash(): string | null {
    if (typeof window === "undefined") return null
    const value = window.location.hash.slice(1).toLowerCase()
    return offices.some((office) => office.id === value) ? value : null
}

interface OfficeDirectoryProps {
    style?: React.CSSProperties
    dubaiButton?: React.ReactNode
    dubaiButtonVi?: React.ReactNode
    vietnamButton?: React.ReactNode
    vietnamButtonVi?: React.ReactNode
    panamaButton?: React.ReactNode
    panamaButtonVi?: React.ReactNode
    georgiaButton?: React.ReactNode
    georgiaButtonVi?: React.ReactNode
}

/**
 * @framerSupportedLayoutWidth any-prefer-fixed
 * @framerSupportedLayoutHeight auto
 */
export default function OfficeDirectory(props: OfficeDirectoryProps) {
    const rootRef = React.useRef<HTMLElement>(null)
    const [language, setLanguage] = useState<Language>(readLanguage)
    const [active, setActive] = useState<string | null>(() => readHash() ?? "dubai")
    const [query, setQuery] = useState("")
    const [compact, setCompact] = useState(false)
    const [narrow, setNarrow] = useState(false)

    useEffect(() => {
        const root = rootRef.current
        if (!root) return
        const measure = () => {
            const width = root.getBoundingClientRect().width
            setCompact(width <= 850)
            setNarrow(width <= 500)
        }
        measure()
        if (typeof ResizeObserver === "undefined") return
        const observer = new ResizeObserver(measure)
        observer.observe(root)
        return () => observer.disconnect()
    }, [])

    useEffect(() => {
        const syncLanguage = () => setLanguage(readLanguage())
        const syncHash = () => {
            const next = readHash()
            if (next) {
                setActive(next)
                setQuery("")
                window.setTimeout(() => document.getElementById(`office-${next}`)?.scrollIntoView({ behavior: "smooth", block: "center" }), 80)
            }
        }
        window.addEventListener("botanika:inline-language", syncLanguage)
        window.addEventListener("storage", syncLanguage)
        window.addEventListener("hashchange", syncHash)
        syncHash()
        return () => {
            window.removeEventListener("botanika:inline-language", syncLanguage)
            window.removeEventListener("storage", syncLanguage)
            window.removeEventListener("hashchange", syncHash)
        }
    }, [])

    const filtered = useMemo(() => {
        const needle = query.trim().toLocaleLowerCase()
        if (!needle) return offices
        return offices.filter((office) => [office.city, office.cityVi, office.country, office.countryVi, office.company, office.address, office.addressVi]
            .some((text) => text.toLocaleLowerCase().includes(needle)))
    }, [query])
    const selected = offices.find((office) => office.id === active) ?? null
    const vi = language === "vi"
    const buttons: Record<string, React.ReactNode> = {
        dubai: vi ? props.dubaiButtonVi : props.dubaiButton,
        vietnam: vi ? props.vietnamButtonVi : props.vietnamButton,
        panama: vi ? props.panamaButtonVi : props.panamaButton,
        georgia: vi ? props.georgiaButtonVi : props.georgiaButton,
    }

    const choose = (office: Office) => {
        const next = active === office.id ? null : office.id
        setActive(next)
        if (typeof window !== "undefined") {
            const url = new URL(window.location.href)
            url.hash = next ?? ""
            window.history.replaceState(null, "", url)
        }
    }

    return <section ref={rootRef} className="botanika-offices" style={{ ...props.style, position: "relative", width: "100%" }} data-botanika-no-translate data-has-selection={selected ? "true" : "false"} data-compact={compact ? "true" : "false"} data-narrow={narrow ? "true" : "false"}>
        <style>{`
            .botanika-offices{color:#f5f5f5;font-family:"Plus Jakarta Sans",Inter,Arial,sans-serif;box-sizing:border-box;}
            .botanika-offices *{box-sizing:border-box;}
            .botanika-offices .od-layout{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.06fr);gap:24px;align-items:start;}
            .botanika-offices .od-search{display:flex;align-items:center;gap:12px;width:100%;height:50px;padding:0 16px;border:1px solid #38383e;border-radius:12px;background:#171719;margin-bottom:16px;color:#a9a9b1;}
            .botanika-offices .od-search input{width:100%;height:100%;border:0;outline:0;background:none;color:#f5f5f5;font:500 15px "Plus Jakarta Sans",Inter,sans-serif;}
            .botanika-offices .od-search input::placeholder{color:#8d8d95;}
            .botanika-offices .od-list{border:1px solid #303034;border-radius:18px;background:#18181b;overflow:hidden;}
            .botanika-offices .od-item+.od-item{border-top:1px solid #303034;}
            .botanika-offices .od-toggle{width:100%;display:flex;align-items:center;gap:14px;padding:21px 22px;background:transparent;border:0;color:#f5f5f5;text-align:left;cursor:pointer;font:600 16px "Plus Jakarta Sans",Inter,sans-serif;transition:background .2s;}
            .botanika-offices .od-toggle:hover,.botanika-offices .od-toggle[aria-expanded="true"]{background:#232327;}
            .botanika-offices .od-flag{font-size:23px;line-height:1;flex:none;}
            .botanika-offices .od-label{flex:1;line-height:1.4;}
            .botanika-offices .od-country{font-weight:400;color:#b8b8bf;}
            .botanika-offices .od-chevron{width:24px;height:24px;flex:0 0 24px;display:grid;place-items:center;color:#b8b8bf;transition:transform .25s;}
            .botanika-offices [aria-expanded="true"] .od-chevron{transform:rotate(45deg);}
            .botanika-offices .od-detail{padding:0 22px 23px 59px;background:#232327;animation:od-open .25s ease both;}
            .botanika-offices .od-company{font-size:18px;font-weight:700;margin:0 0 9px;line-height:1.35;}
            .botanika-offices .od-meta{font-size:14px;line-height:1.65;color:#c4c4ca;margin:5px 0;}
            .botanika-offices .od-email{color:#f5f5f5;text-decoration:none;}
            .botanika-offices .od-email:hover{color:#ff7426;}
            .botanika-offices .od-actions{display:flex;flex-wrap:wrap;gap:10px;margin-top:18px;}
            .botanika-offices .od-cta{display:inline-flex;align-items:center;justify-content:space-between;gap:24px;height:44px;padding:4px 4px 4px 20px;border:0;border-radius:8px;background:#27272a;color:white;text-decoration:none;font-size:14px;font-weight:600;white-space:nowrap;transition:background .2s;}
            .botanika-offices .od-cta:hover{background:#3a3a40;}
            .botanika-offices .od-arrow{display:grid;place-items:center;width:36px;height:36px;background:#fff;border-radius:7px;color:#111;}
            .botanika-offices .od-map{height:510px;border:1px solid #303034;border-radius:18px;overflow:hidden;background:#161618;position:sticky;top:105px;}
            .botanika-offices .od-map iframe{width:100%;height:100%;border:0;display:block;}
            .botanika-offices .od-mobile-map{display:none;}
            .botanika-offices .od-map-empty{height:100%;display:flex;align-items:center;justify-content:center;text-align:center;padding:24px;color:#b8b8bf;font-size:14px;}
            .botanika-offices .od-no-results{padding:30px 22px;color:#b8b8bf;font-size:14px;}
            @keyframes od-open{from{opacity:0;transform:translateY(-5px)}to{opacity:1;transform:translateY(0)}}
            .botanika-offices[data-compact="true"] .od-layout{display:block}
            .botanika-offices[data-compact="true"] .od-map{width:100%;height:360px;position:relative;top:auto;margin-top:18px}
            .botanika-offices[data-compact="true"][data-has-selection="true"] .od-map{display:none}
            .botanika-offices[data-compact="true"] .od-mobile-map{display:block;width:calc(100% + 37px);height:340px;margin:18px 0 0 -37px;border:1px solid #303034;border-radius:12px;overflow:hidden;background:#161618}
            .botanika-offices[data-compact="true"] .od-mobile-map iframe{display:block;width:100%;height:100%;border:0}
            .botanika-offices[data-narrow="true"] .od-map{height:300px}
            .botanika-offices[data-narrow="true"] .od-mobile-map{width:calc(100% + 31px);height:300px;margin-left:-31px}
            .botanika-offices[data-narrow="true"] .od-toggle{padding:18px 16px;font-size:14px;gap:10px}
            .botanika-offices[data-narrow="true"] .od-flag{font-size:21px}
            .botanika-offices[data-narrow="true"] .od-detail{padding:0 16px 20px 47px}
            .botanika-offices[data-narrow="true"] .od-separator{display:none}
            .botanika-offices[data-narrow="true"] .od-country{display:block}
            .botanika-offices[data-narrow="true"] .od-search{height:46px}
        `}</style>
        <div className="od-layout">
            <div>
                <label className="od-search">
                    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" aria-hidden="true"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.2 4.2"/></svg>
                    <input type="search" value={query} onChange={(event) => setQuery(event.target.value)} placeholder={vi ? "Tìm văn phòng hoặc thành phố" : "Search office or city"} aria-label={vi ? "Tìm văn phòng" : "Search offices"} />
                </label>
                <div className="od-list">
                    {filtered.length ? filtered.map((office) => <article className="od-item" id={`office-${office.id}`} key={office.id}>
                        <button type="button" className="od-toggle" aria-expanded={active === office.id} aria-controls={`details-${office.id}`} onClick={() => choose(office)}>
                            <span className="od-flag" aria-hidden="true">{office.flag}</span>
                            <span className="od-label">{vi ? office.cityVi : office.city}<span className="od-separator">, </span><span className="od-country">{vi ? office.countryVi : office.country}</span></span>
                            <span className="od-chevron" aria-hidden="true"><svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round"><path d="M12 5v14M5 12h14"/></svg></span>
                        </button>
                        {active === office.id && <div className="od-detail" id={`details-${office.id}`}>
                            <h3 className="od-company">{office.company}</h3>
                            <p className="od-meta">{vi ? office.addressVi : office.address}</p>
                            <p className="od-meta">{vi ? office.hoursVi : office.hours}</p>
                            <p className="od-meta"><a className="od-email" href="mailto:admin@botanika.ai">admin@botanika.ai</a></p>
                            <div className="od-actions">
                                {buttons[office.id] || <a className="od-cta" href={office.directions} target="_blank" rel="noopener noreferrer">{vi ? "Chỉ đường" : "Get directions"}<span className="od-arrow" aria-hidden="true"><svg width="20" height="20" viewBox="0 0 20 20" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round"><path d="M3.5 10h12m-5-5 5 5-5 5"/></svg></span></a>}
                            </div>
                            <div className="od-mobile-map"><iframe title={vi ? `Bản đồ văn phòng ${office.cityVi}` : `${office.city} office map`} src={`https://maps.google.com/maps?q=${encodeURIComponent(office.mapQuery)}&output=embed&hl=en&gl=US`} loading="lazy" referrerPolicy="no-referrer-when-downgrade" allowFullScreen /></div>
                        </div>}
                    </article>) : <div className="od-no-results">{vi ? "Không tìm thấy văn phòng phù hợp." : "No matching offices found."}</div>}
                </div>
            </div>
            <div className="od-map" aria-label={vi ? "Bản đồ văn phòng" : "Office map"}>
                {selected ? <iframe key={selected.id} title={vi ? `Bản đồ văn phòng ${selected.cityVi}` : `${selected.city} office map`} src={`https://maps.google.com/maps?q=${encodeURIComponent(selected.mapQuery)}&output=embed&hl=en&gl=US`} loading="lazy" referrerPolicy="no-referrer-when-downgrade" allowFullScreen /> : <div className="od-map-empty">{vi ? "Chọn văn phòng để xem bản đồ" : "Select an office to view the map"}</div>}
            </div>
        </div>
    </section>
}

addPropertyControls(OfficeDirectory, {
    dubaiButton: { type: ControlType.Slot, title: "Dubai button", maxCount: 1 },
    dubaiButtonVi: { type: ControlType.Slot, title: "Dubai button VI", maxCount: 1 },
    vietnamButton: { type: ControlType.Slot, title: "Vietnam button", maxCount: 1 },
    vietnamButtonVi: { type: ControlType.Slot, title: "Vietnam button VI", maxCount: 1 },
    panamaButton: { type: ControlType.Slot, title: "Panama button", maxCount: 1 },
    panamaButtonVi: { type: ControlType.Slot, title: "Panama button VI", maxCount: 1 },
    georgiaButton: { type: ControlType.Slot, title: "Georgia button", maxCount: 1 },
    georgiaButtonVi: { type: ControlType.Slot, title: "Georgia button VI", maxCount: 1 },
})
